INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('801d19ca-5e0f-4ec2-8cf2-19053ee93ee5', 'real_estate', NULL, 'What is blockbusting?', '¿Qué es el blockbusting?', '["Inducing panic selling by suggesting that protected classes are moving into an area", "Building large developments", "Buying foreclosed properties", "Investing in real estate"]', '["Inducir ventas por pánico sugiriendo que clases protegidas se están mudando a un área", "Construir grandes desarrollos", "Comprar propiedades en ejecución hipotecaria", "Invertir en bienes raíces"]', 0, 'Blockbusting is the illegal practice of inducing homeowners to sell by suggesting that members of protected classes are moving into the area.', 'El blockbusting es la práctica ilegal de inducir a propietarios a vender sugiriendo que miembros de clases protegidas se están mudando al área.', true, '2026-01-14 22:36:13.264653', '2026-01-14 22:36:13.264653') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('80c62493-0f47-46d8-b499-2f24f9ce3be3', 'real_estate', NULL, 'What is specific performance in a real estate contract?', '¿Qué es el cumplimiento específico en un contrato de bienes raíces?', '["A court order requiring the party to perform as agreed in the contract", "A penalty payment", "A contract cancellation", "A price reduction"]', '["Una orden judicial que requiere que la parte cumpla según lo acordado en el contrato", "Un pago de penalidad", "Una cancelación de contrato", "Una reducción de precio"]', 0, 'Specific performance is a legal remedy where the court orders a party to fulfill their contractual obligations.', 'El cumplimiento específico es un remedio legal donde el tribunal ordena a una parte cumplir con sus obligaciones contractuales.', true, '2026-01-14 22:36:13.092584', '2026-01-14 22:36:13.092584') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('815afd19-034d-4bfc-9a4c-830baf5575ed', 'real_estate', NULL, 'What is a subdivision?', '¿Qué es una subdivisión?', '["The division of land into smaller parcels for sale or development", "A type of zoning", "A mortgage", "A deed"]', '["La división de terreno en parcelas más pequeñas para venta o desarrollo", "Un tipo de zonificación", "Una hipoteca", "Una escritura"]', 0, 'A subdivision is the process of dividing a larger parcel of land into smaller lots for sale or development.', 'Una subdivisión es el proceso de dividir una parcela de terreno más grande en lotes más pequeños para venta o desarrollo.', true, '2026-01-14 22:36:13.369287', '2026-01-14 22:36:13.369287') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('83271e41-2513-49cd-9dae-4391baa3e9c1', 'real_estate', NULL, 'Under TREC rules, when must a license holder provide the Information About Brokerage Services form?', 'Según las reglas de TREC, ¿cuándo debe un titular de licencia proporcionar el formulario de Información Sobre Servicios de Corretaje?', '["At first substantive dialogue", "After signing a listing agreement", "At closing", "When asked by the client"]', '["En el primer diálogo sustancial", "Después de firmar un acuerdo de listado", "Al cierre", "Cuando el cliente lo solicite"]', 0, 'The Information About Brokerage Services form must be provided at the first substantive dialogue with a prospective buyer or seller.', 'El formulario de Información Sobre Servicios de Corretaje debe proporcionarse en el primer diálogo sustancial con un posible comprador o vendedor.', true, '2026-01-14 22:36:12.946354', '2026-01-14 22:36:12.946354') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8604fe27-b9a8-456e-88e1-66bde64a2ed0', 'real_estate', NULL, 'What is the loan-to-value ratio (LTV)?', '¿Qué es la relación préstamo-valor (LTV)?', '["The loan amount divided by the property''s appraised value", "The interest rate on the loan", "The monthly payment amount", "The closing costs"]', '["El monto del préstamo dividido por el valor tasado de la propiedad", "La tasa de interés del préstamo", "El monto del pago mensual", "Los costos de cierre"]', 0, 'LTV is calculated by dividing the loan amount by the property''s appraised value, expressed as a percentage.', 'El LTV se calcula dividiendo el monto del préstamo por el valor tasado de la propiedad, expresado como porcentaje.', true, '2026-01-14 22:36:13.097813', '2026-01-14 22:36:13.097813') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8624b56f-2e8d-4e0d-a040-8b9254d8abd1', 'real_estate', NULL, 'The Seller''s Disclosure Notice in Texas must disclose:', 'El Aviso de Divulgación del Vendedor en Texas debe divulgar:', '["Known defects and conditions affecting the property", "The seller''s reason for selling", "The purchase price paid by the seller", "Future development plans in the area"]', '["Defectos y condiciones conocidas que afectan la propiedad", "La razón del vendedor para vender", "El precio de compra pagado por el vendedor", "Planes de desarrollo futuro en el área"]', 0, 'The Seller''s Disclosure Notice requires sellers to disclose known defects and conditions that materially affect the property.', 'El Aviso de Divulgación del Vendedor requiere que los vendedores divulguen defectos y condiciones conocidas que afectan materialmente la propiedad.', true, '2026-01-14 22:36:13.081182', '2026-01-14 22:36:13.081182') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('868769dd-a6a2-4c67-a772-853481d49d12', 'real_estate', NULL, 'In Texas, a sales agent must work under:', 'En Texas, un agente de ventas debe trabajar bajo:', '["A licensed broker", "Another sales agent", "TREC directly", "The Texas Association of Realtors"]', '["Un corredor licenciado", "Otro agente de ventas", "TREC directamente", "La Asociación de Realtors de Texas"]', 0, 'All Texas sales agents must be sponsored by and work under a licensed broker.', 'Todos los agentes de ventas de Texas deben ser patrocinados y trabajar bajo un corredor licenciado.', true, '2026-01-14 22:36:13.436209', '2026-01-14 22:36:13.436209') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8969f8a7-416b-4ecf-af83-c23fc26e3461', 'real_estate', NULL, 'What organization administers the Texas real estate license exam?', '¿Qué organización administra el examen de licencia de bienes raíces de Texas?', '["Pearson VUE", "TREC directly", "Texas Association of Realtors", "National Association of Realtors"]', '["Pearson VUE", "TREC directamente", "Asociación de Realtors de Texas", "Asociación Nacional de Realtors"]', 0, 'Pearson VUE administers the Texas real estate license examination on behalf of TREC.', 'Pearson VUE administra el examen de licencia de bienes raíces de Texas en nombre de TREC.', true, '2026-01-14 22:36:12.942468', '2026-01-14 22:36:12.942468') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('896f4948-32f8-4b55-98e5-f588a323a8ee', 'real_estate', NULL, 'What are the duties of a fiduciary in a real estate transaction?', '¿Cuáles son los deberes de un fiduciario en una transacción de bienes raíces?', '["Obedience, loyalty, disclosure, confidentiality, accounting, and reasonable care", "Only to complete the sale", "To maximize the agent''s commission", "To keep all information confidential from all parties"]', '["Obediencia, lealtad, divulgación, confidencialidad, contabilidad y cuidado razonable", "Solo completar la venta", "Maximizar la comisión del agente", "Mantener toda la información confidencial de todas las partes"]', 0, 'Fiduciary duties include obedience, loyalty, disclosure, confidentiality, accounting, and reasonable care (OLD CAR).', 'Los deberes fiduciarios incluyen obediencia, lealtad, divulgación, confidencialidad, contabilidad y cuidado razonable.', true, '2026-01-14 22:36:13.01033', '2026-01-14 22:36:13.01033') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('89e1df8f-6267-40fa-8df4-738774d2268f', 'real_estate', NULL, 'What is a walk-through inspection?', '¿Qué es una inspección de recorrido final?', '["A final inspection by the buyer before closing to verify property condition", "The initial home inspection", "The appraisal", "The title search"]', '["Una inspección final por el comprador antes del cierre para verificar la condición de la propiedad", "La inspección inicial de la casa", "La tasación", "La búsqueda de título"]', 0, 'The walk-through is a final inspection before closing to verify the property is in the agreed-upon condition.', 'El recorrido final es una inspección final antes del cierre para verificar que la propiedad está en la condición acordada.', true, '2026-01-14 22:36:13.328817', '2026-01-14 22:36:13.328817') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8bf6fb13-7186-4e0f-bbde-86d2ec5a91e9', 'real_estate', NULL, 'What type of lease has a specific beginning and ending date?', '¿Qué tipo de arrendamiento tiene una fecha específica de inicio y fin?', '["Estate for years", "Estate at will", "Estate at sufferance", "Periodic tenancy"]', '["Patrimonio por años", "Patrimonio a voluntad", "Patrimonio por tolerancia", "Tenencia periódica"]', 0, 'An estate for years is a lease with a definite beginning and ending date, regardless of actual duration.', 'Un patrimonio por años es un arrendamiento con una fecha de inicio y fin definida, independientemente de la duración real.', true, '2026-01-14 22:36:13.404192', '2026-01-14 22:36:13.404192') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8c3354a1-bcda-4384-8e2d-8c45a9993728', 'real_estate', NULL, 'What is constructive eviction?', '¿Qué es el desalojo constructivo?', '["When a landlord''s actions or neglect make the property uninhabitable, forcing the tenant to leave", "A formal eviction notice", "A lease termination by the tenant", "A court-ordered eviction"]', '["Cuando las acciones o negligencia del arrendador hacen la propiedad inhabitable, forzando al inquilino a irse", "Un aviso formal de desalojo", "Una terminación de arrendamiento por el inquilino", "Un desalojo ordenado por el tribunal"]', 0, 'Constructive eviction occurs when the landlord''s actions or failure to act renders the property uninhabitable.', 'El desalojo constructivo ocurre cuando las acciones del arrendador o la falta de actuar hacen la propiedad inhabitable.', true, '2026-01-14 22:36:13.418124', '2026-01-14 22:36:13.418124') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8cdc6094-7133-4566-8fec-001302ca2e75', 'real_estate', NULL, 'What is amortization?', '¿Qué es la amortización?', '["The gradual repayment of a loan through scheduled payments", "The increase in property value", "A type of insurance", "A closing cost"]', '["El pago gradual de un préstamo a través de pagos programados", "El aumento en el valor de la propiedad", "Un tipo de seguro", "Un costo de cierre"]', 0, 'Amortization is the process of paying off a loan over time through regular principal and interest payments.', 'La amortización es el proceso de pagar un préstamo a lo largo del tiempo mediante pagos regulares de principal e intereses.', true, '2026-01-14 18:28:35.406838', '2026-01-14 18:28:35.406838') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8d815a2e-6ba1-40a1-9838-c33e4fa10802', 'real_estate', NULL, 'What is equity in a home?', '¿Qué es el patrimonio en una vivienda?', '["The difference between the property''s market value and the amount owed on it", "The mortgage balance", "The monthly payment", "The interest rate"]', '["La diferencia entre el valor de mercado de la propiedad y el monto adeudado", "El saldo de la hipoteca", "El pago mensual", "La tasa de interés"]', 0, 'Home equity is the difference between what the home is worth and what is still owed on the mortgage.', 'El patrimonio de la vivienda es la diferencia entre lo que vale la casa y lo que aún se debe de la hipoteca.', true, '2026-01-14 22:36:13.149905', '2026-01-14 22:36:13.149905') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8f128cbe-a13b-461d-9c34-cb02069b4705', 'real_estate', NULL, 'What is a home inspection?', '¿Qué es una inspección de vivienda?', '["A professional evaluation of the home''s physical condition", "An appraisal", "A title search", "A survey"]', '["Una evaluación profesional de la condición física de la casa", "Una tasación", "Una búsqueda de título", "Un levantamiento topográfico"]', 0, 'A home inspection is a professional evaluation of a property''s physical condition, typically including structure, systems, and components.', 'Una inspección de vivienda es una evaluación profesional de la condición física de una propiedad, típicamente incluyendo estructura, sistemas y componentes.', true, '2026-01-14 22:36:13.227091', '2026-01-14 22:36:13.227091') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('93175a54-7c58-4420-9f25-4746ac5037c5', 'real_estate', NULL, 'What is the difference between a mortgage and a deed of trust?', '¿Cuál es la diferencia entre una hipoteca y un fideicomiso de título?', '["A deed of trust involves a third-party trustee; a mortgage is between borrower and lender only", "They are identical", "Mortgages are for commercial property only", "Deeds of trust are for residential only"]', '["Un fideicomiso de título involucra un fideicomisario tercero; una hipoteca es solo entre prestatario y prestamista", "Son idénticos", "Las hipotecas son solo para propiedades comerciales", "Los fideicomisos de título son solo para residenciales"]', 0, 'A deed of trust involves three parties (borrower, lender, and trustee), while a mortgage is a two-party agreement.', 'Un fideicomiso de título involucra tres partes (prestatario, prestamista y fideicomisario), mientras que una hipoteca es un acuerdo de dos partes.', true, '2026-01-14 22:36:58.876305', '2026-01-14 22:36:58.876305') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('93bedb7e-12a8-4bdf-bf57-61c6d32c45bb', 'real_estate', NULL, 'What is the purpose of earnest money in a real estate transaction?', '¿Cuál es el propósito del dinero de garantía en una transacción de bienes raíces?', '["To show the buyer''s good faith and serious intent to purchase", "To pay the agent''s commission", "To cover closing costs", "To pay property taxes"]', '["Mostrar la buena fe del comprador y la intención seria de comprar", "Pagar la comisión del agente", "Cubrir los costos de cierre", "Pagar impuestos sobre la propiedad"]', 0, 'Earnest money demonstrates the buyer''s good faith commitment to complete the purchase.', 'El dinero de garantía demuestra el compromiso de buena fe del comprador de completar la compra.', true, '2026-01-14 22:36:13.055916', '2026-01-14 22:36:13.055916') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9406185b-4abc-4bbe-8265-b03f64bdee53', 'real_estate', NULL, 'What is a triple net (NNN) lease?', '¿Qué es un arrendamiento triple neto (NNN)?', '["A lease where the tenant pays rent plus property taxes, insurance, and maintenance", "A lease with three tenants", "A three-year lease", "A residential lease type"]', '["Un arrendamiento donde el inquilino paga alquiler más impuestos sobre la propiedad, seguro y mantenimiento", "Un arrendamiento con tres inquilinos", "Un arrendamiento de tres años", "Un tipo de arrendamiento residencial"]', 0, 'A triple net lease requires the tenant to pay base rent plus property taxes, insurance, and maintenance costs.', 'Un arrendamiento triple neto requiere que el inquilino pague alquiler base más impuestos sobre la propiedad, seguro y costos de mantenimiento.', true, '2026-01-14 22:36:13.413638', '2026-01-14 22:36:13.413638') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('942fbab7-7727-4477-9547-3ec8f014620c', 'real_estate', NULL, 'The cost approach to value is based on:', 'El enfoque de costo para el valor se basa en:', '["The cost to replace or reproduce the property minus depreciation, plus land value", "Comparable sales only", "Rental income", "Tax assessments"]', '["El costo de reemplazar o reproducir la propiedad menos depreciación, más valor del terreno", "Solo ventas comparables", "Ingresos por alquiler", "Evaluaciones fiscales"]', 0, 'The cost approach estimates value by calculating the cost to replace the improvements, subtracting depreciation, and adding land value.', 'El enfoque de costo estima el valor calculando el costo de reemplazar las mejoras, restando la depreciación y agregando el valor del terreno.', true, '2026-01-14 22:36:13.17662', '2026-01-14 22:36:13.17662') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9564ace7-cbd2-42f6-b270-a8b653a9ffff', 'real_estate', NULL, 'Under Texas law, sellers must disclose:', 'Según la ley de Texas, los vendedores deben divulgar:', '["Known material defects affecting the property", "The original purchase price", "Names of previous owners", "Future development plans nearby"]', '["Defectos materiales conocidos que afectan la propiedad", "El precio de compra original", "Nombres de propietarios anteriores", "Planes de desarrollo futuro cercanos"]', 0, 'Texas law requires sellers to disclose known material defects that could affect the property''s value or the buyer''s decision.', 'La ley de Texas requiere que los vendedores divulguen defectos materiales conocidos que podrían afectar el valor de la propiedad o la decisión del comprador.', true, '2026-01-14 22:36:13.214022', '2026-01-14 22:36:13.214022') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('957083e2-10bc-4ebd-9e34-2b993f1e77d4', 'real_estate', NULL, 'What is the maximum penalty TREC can assess for a single violation of the Real Estate License Act?', '¿Cuál es la penalidad máxima que TREC puede imponer por una sola violación de la Ley de Licencias de Bienes Raíces?', '["$5,000", "$10,000", "$1,000", "$25,000"]', '["$5,000", "$10,000", "$1,000", "$25,000"]', 0, 'TREC can assess an administrative penalty of up to $5,000 for each violation of the Real Estate License Act.', 'TREC puede imponer una penalidad administrativa de hasta $5,000 por cada violación de la Ley de Licencias de Bienes Raíces.', true, '2026-01-14 22:36:12.950906', '2026-01-14 22:36:12.950906') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('957d36c0-5388-4a3d-9313-c90316397d7a', 'real_estate', NULL, 'Under TREC rules, how many hours of continuing education are required for license renewal?', 'Según las reglas de TREC, ¿cuántas horas de educación continua se requieren para la renovación de licencia?', '["18 hours", "30 hours", "15 hours", "24 hours"]', '["18 horas", "30 horas", "15 horas", "24 horas"]', 0, 'TREC requires 18 hours of continuing education for license renewal, including specific legal and ethics hours.', 'TREC requiere 18 horas de educación continua para la renovación de licencia, incluyendo horas específicas de legal y ética.', true, '2026-01-14 22:36:12.911658', '2026-01-14 22:36:12.911658') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('95bb3cce-a3ff-48ca-a6a1-a3becb98b64a', 'real_estate', NULL, 'What happens if a buyer defaults on a real estate contract?', '¿Qué sucede si un comprador incumple un contrato de bienes raíces?', '["The seller may keep the earnest money as liquidated damages", "Nothing happens", "The buyer automatically gets a refund", "The seller must still sell"]', '["El vendedor puede quedarse con el dinero de garantía como daños liquidados", "No pasa nada", "El comprador obtiene un reembolso automáticamente", "El vendedor aún debe vender"]', 0, 'If the buyer defaults, the seller typically may keep the earnest money as liquidated damages as specified in the contract.', 'Si el comprador incumple, el vendedor típicamente puede quedarse con el dinero de garantía como daños liquidados según lo especificado en el contrato.', true, '2026-01-14 22:36:13.075487', '2026-01-14 22:36:13.075487') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('979d1530-5d80-4d89-9791-3b65e8855c29', 'real_estate', NULL, 'What is the minimum age requirement to obtain a Texas real estate sales agent license?', '¿Cuál es el requisito de edad mínima para obtener una licencia de agente de ventas de bienes raíces en Texas?', '["18 years old", "21 years old", "25 years old", "16 years old"]', '["18 años", "21 años", "25 años", "16 años"]', 0, 'Texas requires applicants to be at least 18 years of age to obtain a real estate sales agent license.', 'Texas requiere que los solicitantes tengan al menos 18 años de edad para obtener una licencia de agente de ventas de bienes raíces.', true, '2026-01-14 22:36:12.929695', '2026-01-14 22:36:12.929695') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9814c66f-0f8d-40c7-be60-05b4a87cccdf', 'real_estate', NULL, 'What is market value?', '¿Qué es el valor de mercado?', '["The most probable price a property would bring in a competitive market", "The asking price", "The tax assessed value", "The original purchase price"]', '["El precio más probable que una propiedad obtendría en un mercado competitivo", "El precio de venta", "El valor tasado para impuestos", "El precio de compra original"]', 0, 'Market value is the most probable price a property would sell for in a competitive, open market with informed buyers and sellers.', 'El valor de mercado es el precio más probable por el que una propiedad se vendería en un mercado competitivo y abierto con compradores y vendedores informados.', true, '2026-01-14 22:36:13.205771', '2026-01-14 22:36:13.205771') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('984dc748-ac25-403a-b509-1264c49dac4b', 'real_estate', NULL, 'What is a prepayment penalty?', '¿Qué es una penalidad por pago anticipado?', '["A fee charged for paying off a loan before its maturity date", "A late payment fee", "The interest rate", "The down payment"]', '["Una tarifa cobrada por pagar un préstamo antes de su fecha de vencimiento", "Una tarifa por pago atrasado", "La tasa de interés", "El pago inicial"]', 0, 'A prepayment penalty is a fee charged to a borrower who pays off their loan before the scheduled maturity date.', 'Una penalidad por pago anticipado es una tarifa cobrada a un prestatario que paga su préstamo antes de la fecha de vencimiento programada.', true, '2026-01-14 22:36:13.14033', '2026-01-14 22:36:13.14033') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9a816e7e-49e7-4b9b-9b93-2b456e431de6', 'real_estate', NULL, 'What is PITI in mortgage terms?', '¿Qué es PITI en términos hipotecarios?', '["Principal, Interest, Taxes, and Insurance", "Property Income Tax Interest", "Payment Interest Total Index", "Principal Investment Tax Interest"]', '["Principal, Interés, Impuestos y Seguro", "Interés de Impuesto sobre Ingresos de Propiedad", "Índice Total de Interés de Pago", "Interés de Impuesto de Inversión Principal"]', 0, 'PITI represents the four components of a typical monthly mortgage payment: Principal, Interest, Taxes, and Insurance.', 'PITI representa los cuatro componentes de un pago hipotecario mensual típico: Principal, Interés, Impuestos y Seguro.', true, '2026-01-14 22:36:13.119501', '2026-01-14 22:36:13.119501') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9af67bac-c95f-49ba-b6f9-003de0ce1637', 'real_estate', NULL, 'What is a short sale?', '¿Qué es una venta corta?', '["A sale where the proceeds are less than the mortgage balance", "A quick property sale", "A sale without an agent", "A foreclosure auction"]', '["Una venta donde los ingresos son menos que el saldo de la hipoteca", "Una venta rápida de propiedad", "Una venta sin agente", "Una subasta de ejecución hipotecaria"]', 0, 'A short sale occurs when a property is sold for less than the outstanding mortgage balance, with lender approval.', 'Una venta corta ocurre cuando una propiedad se vende por menos que el saldo pendiente de la hipoteca, con aprobación del prestamista.', true, '2026-01-14 18:28:35.490409', '2026-01-14 18:28:35.490409') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9b767710-5cfe-4e02-8413-a36a3d7deb2f', 'real_estate', NULL, 'What is a settlement statement?', '¿Qué es una declaración de liquidación?', '["A document itemizing all costs and credits for buyer and seller at closing", "A loan application", "A purchase offer", "A listing agreement"]', '["Un documento que detalla todos los costos y créditos para comprador y vendedor en el cierre", "Una solicitud de préstamo", "Una oferta de compra", "Un acuerdo de listado"]', 0, 'The settlement statement (Closing Disclosure) itemizes all financial aspects of the transaction for both parties.', 'La declaración de liquidación (Divulgación de Cierre) detalla todos los aspectos financieros de la transacción para ambas partes.', true, '2026-01-14 22:36:13.315565', '2026-01-14 22:36:13.315565') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9cb9b774-e98e-4f3e-99e7-6f627804c599', 'real_estate', NULL, 'Under Texas law, how long does a landlord have to return a security deposit after move-out?', 'Según la ley de Texas, ¿cuánto tiempo tiene un arrendador para devolver un depósito de seguridad después de la mudanza?', '["30 days", "15 days", "60 days", "90 days"]', '["30 días", "15 días", "60 días", "90 días"]', 0, 'Texas law requires landlords to return security deposits within 30 days after the tenant surrenders the property.', 'La ley de Texas requiere que los arrendadores devuelvan los depósitos de seguridad dentro de 30 días después de que el inquilino entregue la propiedad.', true, '2026-01-14 22:36:13.39465', '2026-01-14 22:36:13.39465') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9da1a053-559c-4169-ba96-3b1424bb0831', 'real_estate', NULL, 'What is an environmental impact assessment?', '¿Qué es una evaluación de impacto ambiental?', '["An evaluation of how a proposed development may affect the environment", "A property appraisal", "A home inspection", "A title search"]', '["Una evaluación de cómo un desarrollo propuesto puede afectar el medio ambiente", "Una tasación de propiedad", "Una inspección de casa", "Una búsqueda de título"]', 0, 'An environmental impact assessment evaluates the potential environmental effects of a proposed development project.', 'Una evaluación de impacto ambiental evalúa los efectos ambientales potenciales de un proyecto de desarrollo propuesto.', true, '2026-01-14 22:36:13.378234', '2026-01-14 22:36:13.378234') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9f978652-b959-4811-ad49-e2439a215f67', 'real_estate', NULL, 'What is a dry closing?', '¿Qué es un cierre en seco?', '["A closing where documents are signed but funds are not yet disbursed", "A closing without a title company", "A closing without agents present", "A remote closing"]', '["Un cierre donde los documentos se firman pero los fondos aún no se desembolsan", "Un cierre sin compañía de títulos", "Un cierre sin agentes presentes", "Un cierre remoto"]', 0, 'A dry closing occurs when all documents are signed, but the funds are not disbursed until a later time.', 'Un cierre en seco ocurre cuando todos los documentos se firman, pero los fondos no se desembolsan hasta un momento posterior.', true, '2026-01-14 22:36:13.338356', '2026-01-14 22:36:13.338356') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a028a7f8-8a8e-473e-8624-39c229e3b2d8', 'real_estate', NULL, 'What is steering in real estate?', '¿Qué es el steering en bienes raíces?', '["Directing buyers to or away from certain neighborhoods based on protected classes", "A sales technique", "A closing procedure", "A marketing strategy"]', '["Dirigir a compradores hacia o lejos de ciertos vecindarios basándose en clases protegidas", "Una técnica de ventas", "Un procedimiento de cierre", "Una estrategia de mercadeo"]', 0, 'Steering is an illegal practice of guiding prospective buyers toward or away from neighborhoods based on race or other protected characteristics.', 'El steering es una práctica ilegal de guiar a compradores potenciales hacia o lejos de vecindarios basándose en raza u otras características protegidas.', true, '2026-01-14 18:28:35.535576', '2026-01-14 18:28:35.535576') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a25f2eda-d754-40cb-9fca-f07af123bf18', 'real_estate', NULL, 'What is the statute of frauds?', '¿Qué es el estatuto de fraudes?', '["A law requiring certain contracts to be in writing", "A criminal law", "A zoning regulation", "A licensing requirement"]', '["Una ley que requiere que ciertos contratos estén por escrito", "Una ley penal", "Una regulación de zonificación", "Un requisito de licencia"]', 0, 'The statute of frauds requires that real estate contracts must be in writing to be enforceable.', 'El estatuto de fraudes requiere que los contratos inmobiliarios deben estar por escrito para ser ejecutables.', true, '2026-01-14 18:28:35.422998', '2026-01-14 18:28:35.422998') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a2c00d73-ec99-4270-955d-28ccda57f0ee', 'real_estate', NULL, 'What is a VA loan?', '¿Qué es un préstamo VA?', '["A loan guaranteed by the Department of Veterans Affairs for eligible veterans", "A loan from Virginia", "A variable adjustment loan", "A vacation home loan"]', '["Un préstamo garantizado por el Departamento de Asuntos de Veteranos para veteranos elegibles", "Un préstamo de Virginia", "Un préstamo de ajuste variable", "Un préstamo para casa vacacional"]', 0, 'VA loans are guaranteed by the U.S. Department of Veterans Affairs and available to eligible military veterans and their families.', 'Los préstamos VA son garantizados por el Departamento de Asuntos de Veteranos de EE.UU. y están disponibles para veteranos militares elegibles y sus familias.', true, '2026-01-14 22:36:13.124723', '2026-01-14 22:36:13.124723') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a4cdedf6-6009-4741-b490-478c811ca9be', 'real_estate', NULL, 'Which of the following activities requires a real estate license in Texas?', '¿Cuál de las siguientes actividades requiere una licencia de bienes raíces en Texas?', '["Negotiating a lease for another person for compensation", "Managing your own property", "Selling your own home", "Appraising property"]', '["Negociar un arrendamiento para otra persona por compensación", "Administrar su propia propiedad", "Vender su propia casa", "Tasar propiedades"]', 0, 'Negotiating a lease or sale of real property for another person for compensation requires a Texas real estate license.', 'Negociar un arrendamiento o venta de bienes inmuebles para otra persona por compensación requiere una licencia de bienes raíces de Texas.', true, '2026-01-14 22:36:12.986408', '2026-01-14 22:36:12.986408') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a52ad124-e0e7-45b1-a83f-8f19ce5e6d7b', 'real_estate', NULL, 'What is amortization in a mortgage?', '¿Qué es la amortización en una hipoteca?', '["The process of paying off a loan through regular payments over time", "The interest calculation", "The appraisal process", "The closing process"]', '["El proceso de pagar un préstamo a través de pagos regulares con el tiempo", "El cálculo de interés", "El proceso de tasación", "El proceso de cierre"]', 0, 'Amortization is the process of gradually paying off a mortgage through scheduled periodic payments.', 'La amortización es el proceso de pagar gradualmente una hipoteca a través de pagos periódicos programados.', true, '2026-01-14 22:36:13.156176', '2026-01-14 22:36:13.156176') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a547328d-39a6-4a4f-a4ae-383bcfc28208', 'real_estate', NULL, 'What is steering in real estate?', '¿Qué es el direccionamiento en bienes raíces?', '["Directing buyers to or away from certain neighborhoods based on protected characteristics", "Guiding buyers through the purchase process", "Marketing properties online", "Setting property prices"]', '["Dirigir compradores hacia o lejos de ciertos vecindarios basándose en características protegidas", "Guiar compradores a través del proceso de compra", "Comercializar propiedades en línea", "Establecer precios de propiedades"]', 0, 'Steering is the illegal practice of directing buyers toward or away from neighborhoods based on race or other protected characteristics.', 'El direccionamiento es la práctica ilegal de dirigir compradores hacia o lejos de vecindarios basándose en raza u otras características protegidas.', true, '2026-01-14 22:36:13.260443', '2026-01-14 22:36:13.260443') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a7d86b10-2756-4730-8cfb-0d59b0116263', 'real_estate', NULL, 'What document transfers title from seller to buyer?', '¿Qué documento transfiere el título del vendedor al comprador?', '["The deed", "The mortgage", "The note", "The title insurance policy"]', '["La escritura", "La hipoteca", "El pagaré", "La póliza de seguro de título"]', 0, 'The deed is the legal document that transfers ownership of real property from the seller to the buyer.', 'La escritura es el documento legal que transfiere la propiedad de bienes inmuebles del vendedor al comprador.', true, '2026-01-14 22:36:13.311183', '2026-01-14 22:36:13.311183') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aa93425e-8aae-4ce3-a70e-a959316ae669', 'real_estate', NULL, 'What is an encumbrance on property?', '¿Qué es un gravamen sobre la propiedad?', '["Any claim or restriction that affects the property''s use or value", "An increase in property value", "A type of mortgage", "A property improvement"]', '["Cualquier reclamo o restricción que afecta el uso o valor de la propiedad", "Un aumento en el valor de la propiedad", "Un tipo de hipoteca", "Una mejora de propiedad"]', 0, 'An encumbrance is any claim, lien, charge, or liability that diminishes the value of or restricts the use of property.', 'Un gravamen es cualquier reclamo, gravamen, cargo o responsabilidad que disminuye el valor o restringe el uso de la propiedad.', true, '2026-01-14 18:28:35.562884', '2026-01-14 18:28:35.562884') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ac01011c-a1cd-48e9-bc09-17c5566bd7da', 'real_estate', NULL, 'What is a closing disclosure?', '¿Qué es una divulgación de cierre?', '["A document detailing final loan terms and closing costs", "A marketing brochure", "A property inspection report", "A zoning certificate"]', '["Un documento que detalla los términos finales del préstamo y costos de cierre", "Un folleto de mercadeo", "Un informe de inspección de propiedad", "Un certificado de zonificación"]', 0, 'The Closing Disclosure is a five-page form that provides final details about the mortgage loan including terms, payments, and fees.', 'La Divulgación de Cierre es un formulario de cinco páginas que proporciona detalles finales sobre el préstamo hipotecario incluyendo términos, pagos y tarifas.', true, '2026-01-14 18:28:35.487102', '2026-01-14 18:28:35.487102') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('acc79193-0e24-4b4c-bb9c-ae1eb1bc8b50', 'real_estate', NULL, 'What is the penalty for violating the Fair Housing Act?', '¿Cuál es la penalidad por violar la Ley de Vivienda Justa?', '["Civil fines, damages, and possible criminal penalties", "Only a warning", "No penalties exist", "Automatic license revocation only"]', '["Multas civiles, daños y posibles penalidades criminales", "Solo una advertencia", "No existen penalidades", "Solo revocación automática de licencia"]', 0, 'Fair Housing violations can result in civil fines up to $100,000+, actual and punitive damages, and possible criminal penalties.', 'Las violaciones de Vivienda Justa pueden resultar en multas civiles de hasta $100,000+, daños reales y punitivos, y posibles penalidades criminales.', true, '2026-01-14 22:36:13.289208', '2026-01-14 22:36:13.289208') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('acd7918b-fd97-4ddc-a706-57c69e60bb9e', 'real_estate', NULL, 'Under Fair Housing, which of the following IS permitted?', 'Según la Vivienda Justa, ¿cuál de las siguientes está permitida?', '["Requiring higher income qualifications for all applicants equally", "Refusing to rent to families with children", "Advertising for tenants of a specific religion", "Charging higher rent based on national origin"]', '["Requerir calificaciones de ingresos más altos para todos los solicitantes por igual", "Negarse a alquilar a familias con niños", "Anunciar para inquilinos de una religión específica", "Cobrar alquiler más alto basándose en origen nacional"]', 0, 'Income requirements are permitted as long as they are applied equally to all applicants and are not used as a pretext for discrimination.', 'Los requisitos de ingresos están permitidos siempre que se apliquen por igual a todos los solicitantes y no se usen como pretexto para discriminación.', true, '2026-01-14 22:36:13.274267', '2026-01-14 22:36:13.274267') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('add5b93e-e170-41ea-9fe4-9ad805c4db96', 'real_estate', NULL, 'What is dual agency?', '¿Qué es la agencia dual?', '["When one agent represents both buyer and seller", "Having two agents work together", "A joint listing arrangement", "A referral agreement"]', '["Cuando un agente representa tanto al comprador como al vendedor", "Tener dos agentes trabajando juntos", "Un acuerdo de listado conjunto", "Un acuerdo de referencia"]', 0, 'Dual agency occurs when one agent or brokerage represents both the buyer and seller in the same transaction.', 'La agencia dual ocurre cuando un agente o corretaje representa tanto al comprador como al vendedor en la misma transacción.', true, '2026-01-14 18:28:35.434175', '2026-01-14 18:28:35.434175') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aef3631b-bf5c-4dbc-bc8e-df508626e12c', 'real_estate', NULL, 'Which addendum would be used for a property in a homeowners association?', '¿Qué anexo se usaría para una propiedad en una asociación de propietarios?', '["Addendum for Property Subject to Mandatory Membership in a Property Owners Association", "Third Party Financing Addendum", "Seller Financing Addendum", "Environmental Assessment Addendum"]', '["Anexo para Propiedad Sujeta a Membresía Obligatoria en una Asociación de Propietarios", "Anexo de Financiamiento de Terceros", "Anexo de Financiamiento del Vendedor", "Anexo de Evaluación Ambiental"]', 0, 'The Addendum for Property Subject to Mandatory Membership in a Property Owners Association is required for HOA properties.', 'El Anexo para Propiedad Sujeta a Membresía Obligatoria en una Asociación de Propietarios se requiere para propiedades con HOA.', true, '2026-01-14 22:36:13.084668', '2026-01-14 22:36:13.084668') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('af9b45a3-733c-4bc8-9af9-c425d6eb322b', 'real_estate', NULL, 'What is the option period in a Texas residential contract?', '¿Qué es el período de opción en un contrato residencial de Texas?', '["A negotiated time for the buyer to conduct inspections and terminate without penalty", "The time to close the sale", "The marketing period", "The appraisal time frame"]', '["Un tiempo negociado para que el comprador realice inspecciones y termine sin penalidad", "El tiempo para cerrar la venta", "El período de mercadeo", "El plazo de tasación"]', 0, 'The option period is a negotiated time during which the buyer may conduct inspections and terminate the contract for any reason.', 'El período de opción es un tiempo negociado durante el cual el comprador puede realizar inspecciones y terminar el contrato por cualquier razón.', true, '2026-01-14 22:36:13.052732', '2026-01-14 22:36:13.052732') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b1202ea3-23d1-4bd4-86e8-2a265c8a3de2', 'real_estate', NULL, 'In Texas, when must the Information About Brokerage Services form be provided?', 'En Texas, ¿cuándo debe proporcionarse el formulario de Información sobre Servicios de Corretaje?', '["At the first substantive dialogue about a specific property", "After the contract is signed", "At closing", "Never required"]', '["En el primer diálogo sustantivo sobre una propiedad específica", "Después de firmar el contrato", "En el cierre", "Nunca requerido"]', 0, 'In Texas, the IABS form must be provided at the first substantive dialogue with a prospective buyer, seller, landlord, or tenant.', 'En Texas, el formulario IABS debe proporcionarse en el primer diálogo sustantivo con un posible comprador, vendedor, arrendador o inquilino.', true, '2026-01-14 18:28:35.437271', '2026-01-14 18:28:35.437271') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b2945f90-b40d-4b5a-bdf2-87a6af7a211a', 'real_estate', NULL, 'What is tenancy in common?', '¿Qué es la tenencia en común?', '["Co-ownership where each owner has a distinct share that can be inherited", "Joint tenancy", "A lease agreement", "A mortgage arrangement"]', '["Copropiedad donde cada propietario tiene una parte distinta que puede heredarse", "Tenencia conjunta", "Un contrato de arrendamiento", "Un arreglo hipotecario"]', 0, 'Tenancy in common allows co-owners to hold different percentages of ownership, and shares pass to heirs rather than other owners.', 'La tenencia en común permite a los copropietarios tener diferentes porcentajes de propiedad, y las partes pasan a los herederos en lugar de otros propietarios.', true, '2026-01-14 18:28:35.510292', '2026-01-14 18:28:35.510292') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b2edbb16-f35b-4375-82f6-6844700caab2', 'real_estate', NULL, 'What is functional obsolescence?', '¿Qué es la obsolescencia funcional?', '["A loss of value due to outdated design or features", "Physical damage to the property", "Neighborhood decline", "Market appreciation"]', '["Una pérdida de valor debido a diseño o características obsoletas", "Daño físico a la propiedad", "Deterioro del vecindario", "Apreciación del mercado"]', 0, 'Functional obsolescence is the loss of value due to outdated or inefficient design, layout, or features.', 'La obsolescencia funcional es la pérdida de valor debido a diseño, distribución o características obsoletas o ineficientes.', true, '2026-01-14 22:36:13.197877', '2026-01-14 22:36:13.197877') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b3e40c89-4b56-4677-a5a8-ea014fca8ff2', 'real_estate', NULL, 'What is a condominium?', '¿Qué es un condominio?', '["Individual ownership of a unit with shared ownership of common areas", "A single-family home", "A rental apartment", "A commercial building"]', '["Propiedad individual de una unidad con propiedad compartida de áreas comunes", "Una casa unifamiliar", "Un apartamento de alquiler", "Un edificio comercial"]', 0, 'A condominium involves individual ownership of a unit plus shared ownership of common areas like hallways, pools, and grounds.', 'Un condominio implica propiedad individual de una unidad más propiedad compartida de áreas comunes como pasillos, piscinas y terrenos.', true, '2026-01-14 18:28:35.522455', '2026-01-14 18:28:35.522455') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b450468f-c668-4925-8c07-848f0195f1dc', 'real_estate', NULL, 'What is a mortgage prepayment penalty?', '¿Qué es una penalidad por pago anticipado de hipoteca?', '["A fee charged for paying off a loan early", "A late payment fee", "The closing cost", "An appraisal fee"]', '["Un cargo por pagar un préstamo anticipadamente", "Un cargo por pago tardío", "El costo de cierre", "Un cargo por tasación"]', 0, 'A prepayment penalty is a fee that some lenders charge if you pay off your mortgage early.', 'Una penalidad por pago anticipado es un cargo que algunos prestamistas cobran si pagas tu hipoteca anticipadamente.', true, '2026-01-14 18:28:35.395903', '2026-01-14 18:28:35.395903') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b46a7328-441a-4371-b879-95d3247c69a1', 'real_estate', NULL, 'What is community property in Texas?', '¿Qué es la propiedad comunitaria en Texas?', '["Property acquired during marriage owned equally by both spouses", "Property owned by the community", "Commercial property", "Government property"]', '["Propiedad adquirida durante el matrimonio poseída igualmente por ambos cónyuges", "Propiedad poseída por la comunidad", "Propiedad comercial", "Propiedad del gobierno"]', 0, 'In Texas, community property is any property acquired by either spouse during marriage, owned equally by both spouses.', 'En Texas, la propiedad comunitaria es cualquier propiedad adquirida por cualquier cónyuge durante el matrimonio, poseída igualmente por ambos cónyuges.', true, '2026-01-14 18:28:35.513079', '2026-01-14 18:28:35.513079') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b514a7f3-90b6-4b8c-8b62-495891ee56d7', 'real_estate', NULL, 'What is a nonconforming use?', '¿Qué es un uso no conforme?', '["A legal use that existed before a zoning change and is allowed to continue", "An illegal use of property", "A temporary use permit", "A conditional use"]', '["Un uso legal que existía antes de un cambio de zonificación y se permite continuar", "Un uso ilegal de la propiedad", "Un permiso de uso temporal", "Un uso condicional"]', 0, 'A nonconforming use is a property use that was legal when established but no longer conforms to current zoning, yet is allowed to continue.', 'Un uso no conforme es un uso de propiedad que era legal cuando se estableció pero ya no cumple con la zonificación actual, pero se permite continuar.', true, '2026-01-14 22:36:13.35627', '2026-01-14 22:36:13.35627') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bd126e57-0cf1-4a24-a290-d08d6bb365c1', 'real_estate', NULL, 'What is asbestos?', '¿Qué es el asbesto?', '["A hazardous mineral fiber once used in building materials", "A type of mold", "A foundation material", "A roofing style"]', '["Una fibra mineral peligrosa una vez usada en materiales de construcción", "Un tipo de moho", "Un material de cimentación", "Un estilo de techo"]', 0, 'Asbestos is a hazardous mineral fiber that was commonly used in building materials and can cause serious health issues when disturbed.', 'El asbesto es una fibra mineral peligrosa que fue comúnmente usada en materiales de construcción y puede causar serios problemas de salud cuando se perturba.', true, '2026-01-14 22:36:13.249212', '2026-01-14 22:36:13.249212') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bdbb3680-d439-4100-9fc4-ac440e9e5736', 'real_estate', NULL, 'What is a home equity line of credit (HELOC)?', '¿Qué es una línea de crédito con garantía hipotecaria (HELOC)?', '["A revolving credit line secured by the equity in your home", "A fixed-rate mortgage", "A personal loan", "A credit card"]', '["Una línea de crédito rotativa asegurada por el patrimonio de su casa", "Una hipoteca de tasa fija", "Un préstamo personal", "Una tarjeta de crédito"]', 0, 'A HELOC is a revolving line of credit that uses your home equity as collateral, allowing you to borrow as needed.', 'Una HELOC es una línea de crédito rotativa que usa el patrimonio de su casa como garantía, permitiéndole pedir prestado según sea necesario.', true, '2026-01-14 22:36:13.163717', '2026-01-14 22:36:13.163717') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('be3062ef-c8fe-4c91-8b29-4bad888ac004', 'real_estate', NULL, 'What is an encroachment?', '¿Qué es una invasión?', '["When a structure or improvement illegally extends onto another''s property", "A type of easement", "A mortgage term", "A zoning violation"]', '["Cuando una estructura o mejora se extiende ilegalmente a la propiedad de otro", "Un tipo de servidumbre", "Un término hipotecario", "Una violación de zonificación"]', 0, 'An encroachment occurs when a structure, fence, or other improvement extends beyond property boundaries onto neighboring land.', 'Una invasión ocurre cuando una estructura, cerca u otra mejora se extiende más allá de los límites de la propiedad hacia terreno vecino.', true, '2026-01-14 22:36:13.239627', '2026-01-14 22:36:13.239627') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bf5c02ca-d75f-4343-b147-e5ab144d7224', 'real_estate', NULL, 'What information must an agent disclose to all parties regardless of representation?', '¿Qué información debe divulgar un agente a todas las partes independientemente de la representación?', '["Material facts that affect the property''s value or desirability", "The seller''s minimum acceptable price", "The buyer''s maximum budget", "Personal financial information"]', '["Hechos materiales que afectan el valor o deseabilidad de la propiedad", "El precio mínimo aceptable del vendedor", "El presupuesto máximo del comprador", "Información financiera personal"]', 0, 'Agents must disclose material facts about the property to all parties, regardless of whom they represent.', 'Los agentes deben divulgar hechos materiales sobre la propiedad a todas las partes, independientemente de a quién representen.', true, '2026-01-14 22:36:13.028196', '2026-01-14 22:36:13.028196') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bf7ef6a9-4c41-4b02-abcb-28520d85e280', 'real_estate', NULL, 'What is the purpose of a home inspection?', '¿Cuál es el propósito de una inspección de vivienda?', '["To identify potential problems with the property", "To determine the selling price", "To approve the mortgage", "To transfer title"]', '["Identificar problemas potenciales con la propiedad", "Determinar el precio de venta", "Aprobar la hipoteca", "Transferir el título"]', 0, 'A home inspection evaluates the condition of a property to identify defects or needed repairs before purchase.', 'Una inspección de vivienda evalúa la condición de una propiedad para identificar defectos o reparaciones necesarias antes de la compra.', true, '2026-01-14 18:28:35.460536', '2026-01-14 18:28:35.460536') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c24db5cc-3da1-43eb-9d80-a1c25c755752', 'real_estate', NULL, 'What is an easement?', '¿Qué es una servidumbre?', '["The right to use another person''s land for a specific purpose", "A type of mortgage", "A lease agreement", "A deed restriction"]', '["El derecho a usar la tierra de otra persona para un propósito específico", "Un tipo de hipoteca", "Un contrato de arrendamiento", "Una restricción de escritura"]', 0, 'An easement is a legal right to use another person''s land for a specific purpose, such as a driveway or utility lines.', 'Una servidumbre es el derecho legal de usar la tierra de otra persona para un propósito específico, como una entrada o líneas de servicios públicos.', true, '2026-01-14 18:28:35.311156', '2026-01-14 18:28:35.311156') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c3da97c0-fbb7-4016-ae0b-b5df6ef39a1e', 'real_estate', NULL, 'What is the income approach to valuation primarily used for?', '¿Para qué se usa principalmente el enfoque de ingresos en la valuación?', '["Investment and commercial properties", "Single-family homes", "Vacant land", "New construction"]', '["Propiedades de inversión y comerciales", "Casas unifamiliares", "Terrenos vacantes", "Nueva construcción"]', 0, 'The income approach values properties based on their potential income, making it ideal for rental and commercial properties.', 'El enfoque de ingresos valora propiedades basándose en su ingreso potencial, haciéndolo ideal para propiedades de alquiler y comerciales.', true, '2026-01-14 18:28:35.365887', '2026-01-14 18:28:35.365887') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c6a4967e-3d71-4f73-a190-8f9593b8d575', 'real_estate', NULL, 'What is the term for a licensed sales agent working under a broker''s supervision?', '¿Cuál es el término para un agente de ventas licenciado que trabaja bajo la supervisión de un corredor?', '["Sponsored sales agent", "Associate broker", "Apprentice", "Junior agent"]', '["Agente de ventas patrocinado", "Corredor asociado", "Aprendiz", "Agente junior"]', 0, 'In Texas, a sales agent must be sponsored by a licensed broker to engage in real estate activities.', 'En Texas, un agente de ventas debe ser patrocinado por un corredor licenciado para participar en actividades de bienes raíces.', true, '2026-01-14 22:36:12.9899', '2026-01-14 22:36:12.9899') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c6f69e60-4e70-4f23-bce4-e68cf1c9d36c', 'real_estate', NULL, 'In an intermediary relationship, an appointed licensee may:', 'En una relación de intermediario, un licenciatario designado puede:', '["Provide advice and opinions to their appointed party", "Share confidential information between parties", "Negotiate for both parties equally", "Act as a neutral mediator only"]', '["Proporcionar consejos y opiniones a su parte designada", "Compartir información confidencial entre partes", "Negociar para ambas partes por igual", "Actuar solo como mediador neutral"]', 0, 'An appointed licensee in an intermediary relationship may provide advice and opinions to the party they are appointed to represent.', 'Un licenciatario designado en una relación de intermediario puede proporcionar consejos y opiniones a la parte que está designado a representar.', true, '2026-01-14 22:36:13.031133', '2026-01-14 22:36:13.031133') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8424aff-3029-4d0e-afae-7e8a4ad92732', 'real_estate', NULL, 'What is the Texas Real Estate License Act (TRELA)?', '¿Qué es la Ley de Licencias de Bienes Raíces de Texas (TRELA)?', '["The law governing real estate licensing in Texas", "A federal law", "A zoning regulation", "A mortgage law"]', '["La ley que rige las licencias de bienes raíces en Texas", "Una ley federal", "Una regulación de zonificación", "Una ley hipotecaria"]', 0, 'TRELA is the Texas statute that establishes requirements for real estate licensing and agent conduct in Texas.', 'TRELA es el estatuto de Texas que establece requisitos para licencias de bienes raíces y conducta de agentes en Texas.', true, '2026-01-14 18:28:35.50373', '2026-01-14 18:28:35.50373') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8cb52ea-aeab-4c5a-8b38-d2cec238be03', 'real_estate', NULL, 'A buyer''s agent owes the buyer:', 'Un agente del comprador le debe al comprador:', '["Full fiduciary duties", "Only the duty of honesty", "No specific duties", "Only the duty to complete paperwork"]', '["Todos los deberes fiduciarios", "Solo el deber de honestidad", "Ningún deber específico", "Solo el deber de completar documentos"]', 0, 'A buyer''s agent owes full fiduciary duties to the buyer, including loyalty, obedience, disclosure, confidentiality, accounting, and reasonable care.', 'Un agente del comprador debe todos los deberes fiduciarios al comprador, incluyendo lealtad, obediencia, divulgación, confidencialidad, contabilidad y cuidado razonable.', true, '2026-01-14 22:36:13.035209', '2026-01-14 22:36:13.035209') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8dd500e-b5eb-45fc-b8b2-c7e66f71a9bd', 'real_estate', NULL, 'What is joint tenancy?', '¿Qué es la tenencia conjunta?', '["A form of co-ownership with right of survivorship", "Renting with a roommate", "A commercial lease", "A type of mortgage"]', '["Una forma de copropiedad con derecho de supervivencia", "Alquilar con un compañero de cuarto", "Un arrendamiento comercial", "Un tipo de hipoteca"]', 0, 'Joint tenancy is a form of property ownership where two or more people own property together with equal rights and right of survivorship.', 'La tenencia conjunta es una forma de propiedad donde dos o más personas poseen propiedad juntas con derechos iguales y derecho de supervivencia.', true, '2026-01-14 18:28:35.507122', '2026-01-14 18:28:35.507122') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8df0b68-07cd-478b-a12c-d1b396733660', 'real_estate', NULL, 'Which party pays the commission does NOT determine:', 'Qué parte paga la comisión NO determina:', '["Agency representation", "The amount of the commission", "Tax deductibility", "Closing costs"]', '["La representación de agencia", "El monto de la comisión", "La deducibilidad fiscal", "Los costos de cierre"]', 0, 'Who pays the commission does not determine which party an agent represents; agency is established by agreement.', 'Quién paga la comisión no determina a qué parte representa un agente; la agencia se establece por acuerdo.', true, '2026-01-14 22:36:13.038904', '2026-01-14 22:36:13.038904') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c9b08d3c-b932-4272-a083-f02a44938390', 'real_estate', NULL, 'What is a fixture in real estate?', '¿Qué es un accesorio en bienes raíces?', '["Personal property that has become permanently attached to real property", "Furniture", "A portable appliance", "A vehicle"]', '["Propiedad personal que se ha adjuntado permanentemente a la propiedad inmueble", "Muebles", "Un electrodoméstico portátil", "Un vehículo"]', 0, 'A fixture is personal property that has been attached to real property in such a way that it becomes part of the real estate.', 'Un accesorio es propiedad personal que se ha adjuntado a la propiedad inmueble de tal manera que se convierte en parte de los bienes raíces.', true, '2026-01-14 18:28:35.551524', '2026-01-14 18:28:35.551524') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ca8b88b2-5e58-4a89-9853-bc72cc89734e', 'real_estate', NULL, 'An agent''s duty of loyalty requires the agent to:', 'El deber de lealtad de un agente requiere que el agente:', '["Put the client''s interests above all others, including the agent''s own", "Always agree with the client", "Never negotiate on price", "Share all information with other parties"]', '["Poner los intereses del cliente por encima de todos los demás, incluyendo los propios", "Siempre estar de acuerdo con el cliente", "Nunca negociar sobre el precio", "Compartir toda la información con otras partes"]', 0, 'The duty of loyalty requires an agent to place the client''s interests above all others, including the agent''s own interests.', 'El deber de lealtad requiere que un agente coloque los intereses del cliente por encima de todos los demás, incluyendo los propios intereses del agente.', true, '2026-01-14 22:36:13.022619', '2026-01-14 22:36:13.022619') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ca8cb5b3-5924-4903-9cd8-369f505da73e', 'real_estate', NULL, 'A real estate licensee must treat all parties to a transaction:', 'Un licenciatario de bienes raíces debe tratar a todas las partes de una transacción:', '["Honestly and fairly", "Equally in all respects", "As fiduciaries", "With no obligations"]', '["Honesta y justamente", "Igualmente en todos los aspectos", "Como fiduciarios", "Sin obligaciones"]', 0, 'All parties must be treated honestly and fairly, though fiduciary duties are owed only to the client.', 'Todas las partes deben ser tratadas honesta y justamente, aunque los deberes fiduciarios se deben solo al cliente.', true, '2026-01-14 22:36:13.296437', '2026-01-14 22:36:13.296437') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cb23d4cc-8b17-441a-b4de-fd65f98b3e06', 'real_estate', NULL, 'What is the implied warranty of habitability?', '¿Qué es la garantía implícita de habitabilidad?', '["The landlord''s legal obligation to maintain rental property in livable condition", "A written lease requirement", "A tenant''s responsibility", "An insurance policy"]', '["La obligación legal del arrendador de mantener la propiedad de alquiler en condiciones habitables", "Un requisito de arrendamiento escrito", "Una responsabilidad del inquilino", "Una póliza de seguro"]', 0, 'The implied warranty of habitability requires landlords to maintain rental properties in a condition fit for human habitation.', 'La garantía implícita de habitabilidad requiere que los arrendadores mantengan las propiedades de alquiler en una condición apta para habitación humana.', true, '2026-01-14 22:36:13.411107', '2026-01-14 22:36:13.411107') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ccf8345f-dccc-4c01-9585-84fbbbc13eaa', 'real_estate', NULL, 'What is the difference between a landlord and a lessor?', '¿Cuál es la diferencia entre un arrendador y un lessor?', '["They mean the same thing - the owner who rents property to others", "Landlord owns; lessor manages", "Lessor is the tenant", "They are opposites"]', '["Significan lo mismo - el propietario que alquila propiedad a otros", "El arrendador posee; el lessor administra", "El lessor es el inquilino", "Son opuestos"]', 0, 'Landlord and lessor are interchangeable terms for the property owner who rents to a tenant (lessee).', 'Arrendador y lessor son términos intercambiables para el propietario que alquila a un inquilino (arrendatario).', true, '2026-01-14 22:36:13.388491', '2026-01-14 22:36:13.388491') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cd0bf9dc-3052-40e2-870d-9748799529f6', 'real_estate', NULL, 'What is a conventional loan?', '¿Qué es un préstamo convencional?', '["A mortgage not insured by a government agency", "An FHA loan", "A VA loan", "A USDA loan"]', '["Una hipoteca no asegurada por una agencia gubernamental", "Un préstamo FHA", "Un préstamo VA", "Un préstamo USDA"]', 0, 'A conventional loan is a mortgage that is not insured or guaranteed by a government agency like FHA, VA, or USDA.', 'Un préstamo convencional es una hipoteca que no está asegurada ni garantizada por una agencia gubernamental como FHA, VA o USDA.', true, '2026-01-14 18:28:35.373418', '2026-01-14 18:28:35.373418') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cd5b9a48-d1ef-4da8-acf6-7b6e27ac2125', 'real_estate', NULL, 'What is the purpose of a real estate appraisal?', '¿Cuál es el propósito de una tasación de bienes raíces?', '["To determine the fair market value of a property", "To inspect for defects", "To determine property taxes", "To measure the property"]', '["Determinar el valor justo de mercado de una propiedad", "Inspeccionar por defectos", "Determinar impuestos sobre la propiedad", "Medir la propiedad"]', 0, 'An appraisal is an unbiased professional opinion of a property''s fair market value.', 'Una tasación es una opinión profesional imparcial del valor justo de mercado de una propiedad.', true, '2026-01-14 22:36:13.169012', '2026-01-14 22:36:13.169012') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cee824ac-0170-4dcb-ad75-afe4c540e261', 'real_estate', NULL, 'What is an eviction?', '¿Qué es un desalojo?', '["The legal process of removing a tenant from a property", "A lease renewal", "A security deposit refund", "A rent increase"]', '["El proceso legal de remover a un inquilino de una propiedad", "Una renovación de arrendamiento", "Un reembolso de depósito de seguridad", "Un aumento de alquiler"]', 0, 'Eviction is the legal process by which a landlord removes a tenant from rental property, typically for lease violations or nonpayment.', 'El desalojo es el proceso legal por el cual un arrendador remueve a un inquilino de una propiedad de alquiler, típicamente por violaciones del arrendamiento o falta de pago.', true, '2026-01-14 22:36:13.401087', '2026-01-14 22:36:13.401087') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cfd6ee34-5041-4b98-840b-05bd90983d52', 'real_estate', NULL, 'What is eminent domain?', '¿Qué es el dominio eminente?', '["The government''s right to take private property for public use with compensation", "A type of property tax", "A zoning restriction", "A mortgage default"]', '["El derecho del gobierno a tomar propiedad privada para uso público con compensación", "Un tipo de impuesto sobre la propiedad", "Una restricción de zonificación", "Un incumplimiento hipotecario"]', 0, 'Eminent domain is the government''s constitutional right to take private property for public use, with just compensation paid to the owner.', 'El dominio eminente es el derecho constitucional del gobierno de tomar propiedad privada para uso público, con compensación justa pagada al propietario.', true, '2026-01-14 18:28:35.328963', '2026-01-14 18:28:35.328963') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d2c63774-0a96-4212-b3f9-eb7ddfd002fa', 'real_estate', NULL, 'What test determines if an item is a fixture?', '¿Qué prueba determina si un artículo es un accesorio?', '["Method of attachment, adaptation, intention, and relationship of parties", "Color of the item", "Age of the item", "Brand of the item"]', '["Método de fijación, adaptación, intención y relación de las partes", "Color del artículo", "Edad del artículo", "Marca del artículo"]', 0, 'Courts use the MARIA test: Method of attachment, Adaptation to property, Relationship of parties, Intent, and Agreement.', 'Los tribunales usan la prueba MARIA: Método de fijación, Adaptación a la propiedad, Relación de las partes, Intención y Acuerdo.', true, '2026-01-14 18:28:35.553995', '2026-01-14 18:28:35.553995') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d335cc13-489c-474f-b1fa-a4dabdc9685a', 'real_estate', NULL, 'What is the purpose of title insurance?', '¿Cuál es el propósito del seguro de título?', '["To protect against defects or claims against the property''s title", "To insure against property damage", "To cover mortgage payments", "To pay property taxes"]', '["Proteger contra defectos o reclamos contra el título de la propiedad", "Asegurar contra daños a la propiedad", "Cubrir pagos de hipoteca", "Pagar impuestos sobre la propiedad"]', 0, 'Title insurance protects against financial loss from defects in the title or unknown liens and encumbrances.', 'El seguro de título protege contra pérdida financiera por defectos en el título o gravámenes y cargas desconocidos.', true, '2026-01-14 22:36:13.252965', '2026-01-14 22:36:13.252965') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d529d53b-c91e-4f00-a8f8-c8027762c97d', 'real_estate', NULL, 'Under Texas law, a real estate broker must maintain a trust account at:', 'Según la ley de Texas, un corredor de bienes raíces debe mantener una cuenta fiduciaria en:', '["A federally insured bank in Texas", "Any bank in the United States", "A credit union only", "The broker''s personal bank"]', '["Un banco asegurado federalmente en Texas", "Cualquier banco en Estados Unidos", "Solo una cooperativa de crédito", "El banco personal del corredor"]', 0, 'Texas law requires brokers to maintain trust accounts at federally insured financial institutions in Texas.', 'La ley de Texas requiere que los corredores mantengan cuentas fiduciarias en instituciones financieras aseguradas federalmente en Texas.', true, '2026-01-14 22:36:12.966037', '2026-01-14 22:36:12.966037') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d555e350-506e-4109-8445-400a02851ea5', 'real_estate', NULL, 'What does it mean when a property goes into foreclosure?', '¿Qué significa cuando una propiedad entra en ejecución hipotecaria?', '["The lender is seizing the property due to default on mortgage payments", "The property is being sold by the owner", "The property is being rented", "The property is being renovated"]', '["El prestamista está embargando la propiedad debido a incumplimiento en los pagos de la hipoteca", "La propiedad está siendo vendida por el propietario", "La propiedad está siendo alquilada", "La propiedad está siendo renovada"]', 0, 'Foreclosure occurs when a lender takes legal action to seize and sell a property because the borrower has defaulted on mortgage payments.', 'La ejecución hipotecaria ocurre cuando un prestamista toma acción legal para embargar y vender una propiedad porque el prestatario ha incumplido los pagos de la hipoteca.', true, '2026-01-14 22:36:13.144721', '2026-01-14 22:36:13.144721') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d66bd489-4f71-4be6-ac47-b9a54787ba34', 'real_estate', NULL, 'What is fee simple absolute ownership?', '¿Qué es la propiedad de pleno dominio absoluto?', '["The most complete form of ownership", "A lease arrangement", "Shared ownership", "Government ownership"]', '["La forma más completa de propiedad", "Un acuerdo de arrendamiento", "Propiedad compartida", "Propiedad del gobierno"]', 0, 'Fee simple absolute is the most complete form of property ownership, giving the owner full rights to use, sell, or transfer the property.', 'El pleno dominio absoluto es la forma más completa de propiedad, otorgando al propietario todos los derechos para usar, vender o transferir la propiedad.', true, '2026-01-14 18:28:35.316315', '2026-01-14 18:28:35.316315') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d871187f-3b88-4996-9886-30144fba92c4', 'real_estate', NULL, 'What is a lien on a property?', '¿Qué es un gravamen sobre una propiedad?', '["A type of property tax", "A legal claim against a property used as collateral", "The property''s market value", "The property''s zoning classification"]', '["Un tipo de impuesto sobre la propiedad", "Un reclamo legal contra una propiedad utilizada como garantía", "El valor de mercado de la propiedad", "La clasificación de zonificación de la propiedad"]', 1, 'A lien is a legal right or interest that a creditor has in the debtor''s property, usually as security for a debt.', 'Un gravamen es un derecho legal o interés que un acreedor tiene en la propiedad del deudor, generalmente como garantía de una deuda.', true, '2026-01-14 16:50:01.927358', '2026-01-14 16:50:01.927358') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dee0ee91-010f-4852-b168-a34ab124cc95', 'real_estate', NULL, 'What is the purpose of a title search?', '¿Cuál es el propósito de una búsqueda de título?', '["To examine public records and verify the seller has clear title to transfer", "To determine property value", "To inspect the property condition", "To calculate closing costs"]', '["Examinar registros públicos y verificar que el vendedor tiene título claro para transferir", "Determinar el valor de la propiedad", "Inspeccionar la condición de la propiedad", "Calcular costos de cierre"]', 0, 'A title search examines public records to verify ownership and identify any liens, encumbrances, or defects in the title.', 'Una búsqueda de título examina registros públicos para verificar la propiedad e identificar cualquier gravamen, carga o defecto en el título.', true, '2026-01-14 22:36:13.303854', '2026-01-14 22:36:13.303854') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e2793177-e012-47ec-9988-ae4e47c035a4', 'real_estate', NULL, 'What does TREC stand for?', '¿Qué significa TREC?', '["Texas Real Estate Commission", "Texas Residential Education Center", "Transaction Real Estate Contract", "Total Real Estate Compliance"]', '["Comisión de Bienes Raíces de Texas", "Centro de Educación Residencial de Texas", "Contrato de Transacción de Bienes Raíces", "Cumplimiento Total de Bienes Raíces"]', 0, 'TREC is the Texas Real Estate Commission, the state agency that regulates real estate professionals in Texas.', 'TREC es la Comisión de Bienes Raíces de Texas, la agencia estatal que regula a los profesionales de bienes raíces en Texas.', true, '2026-01-14 18:28:35.440293', '2026-01-14 18:28:35.440293') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e4b61c24-ce8e-473a-9661-864fa7c2194d', 'real_estate', NULL, 'What is the capitalization rate (cap rate)?', '¿Qué es la tasa de capitalización (cap rate)?', '["Net operating income divided by property value or price", "The interest rate on a mortgage", "The tax rate", "The appreciation rate"]', '["Ingreso operativo neto dividido por el valor o precio de la propiedad", "La tasa de interés de una hipoteca", "La tasa de impuestos", "La tasa de apreciación"]', 0, 'The cap rate is calculated by dividing the net operating income by the property''s value, used to evaluate investment properties.', 'La tasa de capitalización se calcula dividiendo el ingreso operativo neto por el valor de la propiedad, usado para evaluar propiedades de inversión.', true, '2026-01-14 22:36:13.210389', '2026-01-14 22:36:13.210389') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e693f374-7d6a-440b-a300-22305acfb39b', 'real_estate', NULL, 'What is adverse possession?', '¿Qué es la posesión adversa?', '["A legal method to acquire title to land through continuous use over time", "A type of mortgage", "A lease agreement", "Government seizure"]', '["Un método legal para adquirir título de tierra a través del uso continuo en el tiempo", "Un tipo de hipoteca", "Un contrato de arrendamiento", "Confiscación del gobierno"]', 0, 'Adverse possession allows someone to claim ownership of land by using it openly, continuously, and hostilely for a statutory period.', 'La posesión adversa permite a alguien reclamar propiedad de tierra usándola abiertamente, continuamente y hostilmente durante un período legal.', true, '2026-01-14 18:28:35.333168', '2026-01-14 18:28:35.333168') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e8448c5a-615d-4227-8df1-1e1960c5604e', 'real_estate', NULL, 'What must a broker do upon receiving earnest money from a buyer?', '¿Qué debe hacer un corredor al recibir dinero de garantía de un comprador?', '["Deposit it in the trust account by the close of the second business day", "Immediately give it to the seller", "Hold it personally for 30 days", "Deposit it in the broker''s personal account"]', '["Depositarlo en la cuenta fiduciaria antes del cierre del segundo día hábil", "Entregarlo inmediatamente al vendedor", "Retenerlo personalmente por 30 días", "Depositarlo en la cuenta personal del corredor"]', 0, 'Texas law requires earnest money to be deposited in the broker''s trust account by the close of the second business day after receipt.', 'La ley de Texas requiere que el dinero de garantía se deposite en la cuenta fiduciaria del corredor antes del cierre del segundo día hábil después de recibirlo.', true, '2026-01-14 22:36:13.002952', '2026-01-14 22:36:13.002952') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e919c4ba-4abd-4a59-add0-e335fad19a8e', 'real_estate', NULL, 'What is proration at closing?', '¿Qué es el prorrateo en el cierre?', '["Dividing expenses between buyer and seller based on the closing date", "Adding up all costs", "Calculating the commission", "Determining the loan amount"]', '["Dividir gastos entre comprador y vendedor basándose en la fecha de cierre", "Sumar todos los costos", "Calcular la comisión", "Determinar el monto del préstamo"]', 0, 'Proration is the process of dividing property expenses, such as taxes and HOA fees, between buyer and seller based on the closing date.', 'El prorrateo es el proceso de dividir gastos de la propiedad, como impuestos y cuotas de HOA, entre comprador y vendedor basándose en la fecha de cierre.', true, '2026-01-14 22:36:13.306997', '2026-01-14 22:36:13.306997') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ed8baa4c-2444-4b0f-9593-c0fb17e885c0', 'real_estate', NULL, 'The sales comparison approach to value uses:', 'El enfoque de comparación de ventas para el valor utiliza:', '["Recent sales of similar properties to estimate value", "The cost to build the property", "The income the property generates", "Government assessments only"]', '["Ventas recientes de propiedades similares para estimar el valor", "El costo de construir la propiedad", "Los ingresos que genera la propiedad", "Solo evaluaciones del gobierno"]', 0, 'The sales comparison approach estimates value by comparing the subject property to similar properties that have recently sold.', 'El enfoque de comparación de ventas estima el valor comparando la propiedad sujeto con propiedades similares que se han vendido recientemente.', true, '2026-01-14 22:36:13.172706', '2026-01-14 22:36:13.172706') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f083bba2-29e9-4a4d-a663-070b385385a3', 'real_estate', NULL, 'What is the bundle of rights in real estate?', '¿Qué es el conjunto de derechos en bienes raíces?', '["Rights of possession, control, enjoyment, exclusion, and disposition", "Rights to mortgage only", "Rights to lease only", "Rights granted by the government"]', '["Derechos de posesión, control, disfrute, exclusión y disposición", "Derechos solo para hipotecar", "Derechos solo para arrendar", "Derechos otorgados por el gobierno"]', 0, 'The bundle of rights includes possession, control, enjoyment, exclusion, and disposition of property.', 'El conjunto de derechos incluye posesión, control, disfrute, exclusión y disposición de la propiedad.', true, '2026-01-14 18:28:35.306512', '2026-01-14 18:28:35.306512') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f09ddc1b-6072-4e3e-b9e3-02c63c13ccb5', 'real_estate', NULL, 'What is zoning?', '¿Qué es la zonificación?', '["Government regulation of land use", "A type of deed", "A mortgage provision", "An insurance requirement"]', '["Regulación gubernamental del uso de la tierra", "Un tipo de escritura", "Una disposición hipotecaria", "Un requisito de seguro"]', 0, 'Zoning is a system of government regulation that divides land into districts with specific permitted uses.', 'La zonificación es un sistema de regulación gubernamental que divide la tierra en distritos con usos específicos permitidos.', true, '2026-01-14 18:28:35.46497', '2026-01-14 18:28:35.46497') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f32d9b7c-53a0-49c0-a892-b511a6040009', 'real_estate', NULL, 'What is appreciation in real estate?', '¿Qué es la apreciación en bienes raíces?', '["An increase in property value over time", "A decrease in property value", "A tax assessment", "A mortgage payment"]', '["Un aumento en el valor de la propiedad con el tiempo", "Una disminución en el valor de la propiedad", "Una evaluación fiscal", "Un pago de hipoteca"]', 0, 'Appreciation is the increase in a property''s value over time due to market conditions, improvements, or other factors.', 'La apreciación es el aumento en el valor de una propiedad con el tiempo debido a condiciones del mercado, mejoras u otros factores.', true, '2026-01-14 18:28:35.477544', '2026-01-14 18:28:35.477544') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f53ea526-2771-401c-874b-474ab3208f94', 'real_estate', NULL, 'What is a lease option?', '¿Qué es una opción de arrendamiento?', '["A lease agreement that includes an option to purchase the property", "A type of mortgage", "A sublease arrangement", "A property management contract"]', '["Un contrato de arrendamiento que incluye una opción para comprar la propiedad", "Un tipo de hipoteca", "Un acuerdo de subarrendamiento", "Un contrato de administración de propiedades"]', 0, 'A lease option allows a tenant to rent a property with the right to purchase it at a predetermined price during or at the end of the lease.', 'Una opción de arrendamiento permite a un inquilino alquilar una propiedad con el derecho de comprarla a un precio predeterminado durante o al final del arrendamiento.', true, '2026-01-14 18:28:35.515908', '2026-01-14 18:28:35.515908') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f76576c6-321b-4bc6-8d0a-e7a314fffe8f', 'real_estate', NULL, 'What is the primary purpose of a deed?', '¿Cuál es el propósito principal de una escritura?', '["To transfer ownership of real property", "To provide insurance coverage", "To establish a lease agreement", "To create a mortgage"]', '["Transferir la propiedad de bienes inmuebles", "Proporcionar cobertura de seguro", "Establecer un contrato de arrendamiento", "Crear una hipoteca"]', 0, 'A deed is a legal document that transfers ownership of real property from one party to another.', 'Una escritura es un documento legal que transfiere la propiedad de bienes inmuebles de una parte a otra.', true, '2026-01-14 16:50:01.810823', '2026-01-14 16:50:01.810823') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f7b56e0f-97d7-408d-a190-c64ecb6fbd75', 'real_estate', NULL, 'In the TREC One to Four Family Residential Contract, the effective date is:', 'En el Contrato Residencial de Una a Cuatro Familias de TREC, la fecha efectiva es:', '["The date the last party signs and communicates acceptance", "The date the contract is written", "The closing date", "The date earnest money is received"]', '["La fecha en que la última parte firma y comunica la aceptación", "La fecha en que se escribe el contrato", "La fecha de cierre", "La fecha en que se recibe el dinero de garantía"]', 0, 'The effective date is when the last party to sign the contract communicates acceptance to the other party.', 'La fecha efectiva es cuando la última parte en firmar el contrato comunica la aceptación a la otra parte.', true, '2026-01-14 22:36:13.062547', '2026-01-14 22:36:13.062547') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f7f4efec-3a0d-4473-ba95-ed09b07363c2', 'real_estate', NULL, 'A Texas real estate license must be renewed every:', 'Una licencia de bienes raíces de Texas debe renovarse cada:', '["2 years", "1 year", "3 years", "5 years"]', '["2 años", "1 año", "3 años", "5 años"]', 0, 'Texas real estate licenses must be renewed every two years from the date of issuance.', 'Las licencias de bienes raíces de Texas deben renovarse cada dos años a partir de la fecha de emisión.', true, '2026-01-14 22:36:12.955697', '2026-01-14 22:36:12.955697') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f9f37685-cadd-4951-ad46-8a44d7ac2d89', 'real_estate', NULL, 'Under the Statute of Frauds, which contracts must be in writing?', 'Según el Estatuto de Fraudes, ¿qué contratos deben ser por escrito?', '["Contracts for the sale of real property", "All verbal agreements", "Only commercial leases", "Short-term rental agreements"]', '["Contratos para la venta de bienes inmuebles", "Todos los acuerdos verbales", "Solo arrendamientos comerciales", "Acuerdos de alquiler a corto plazo"]', 0, 'The Statute of Frauds requires contracts for the sale of real property to be in writing to be enforceable.', 'El Estatuto de Fraudes requiere que los contratos para la venta de bienes inmuebles estén por escrito para ser ejecutables.', true, '2026-01-14 22:36:13.049224', '2026-01-14 22:36:13.049224') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fa09bdf8-561f-4c38-bdb2-10ef3c32b0b9', 'real_estate', NULL, 'What is a homestead exemption in Texas?', '¿Qué es una exención de vivienda en Texas?', '["A property tax reduction for primary residences", "A type of mortgage", "A lease agreement", "Government seizure protection"]', '["Una reducción de impuestos sobre la propiedad para residencias principales", "Un tipo de hipoteca", "Un contrato de arrendamiento", "Protección contra confiscación del gobierno"]', 0, 'In Texas, the homestead exemption reduces the appraised value of a primary residence for property tax purposes.', 'En Texas, la exención de vivienda reduce el valor tasado de una residencia principal para propósitos de impuestos sobre la propiedad.', true, '2026-01-14 18:28:35.348891', '2026-01-14 18:28:35.348891') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fa974e44-d5de-480f-9ebd-9381ab94195a', 'real_estate', NULL, 'How many classroom hours of qualifying education are required for a Texas sales agent license?', '¿Cuántas horas de educación calificada en aula se requieren para una licencia de agente de ventas en Texas?', '["180 hours", "150 hours", "120 hours", "90 hours"]', '["180 horas", "150 horas", "120 horas", "90 horas"]', 0, 'Texas requires 180 classroom hours of qualifying education for a sales agent license.', 'Texas requiere 180 horas de educación calificada en aula para una licencia de agente de ventas.', true, '2026-01-14 22:36:12.934593', '2026-01-14 22:36:12.934593') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fafd7147-28d4-431d-b7c9-5544cd06c37b', 'real_estate', NULL, 'What is a purchase agreement?', '¿Qué es un contrato de compra?', '["A legally binding contract between buyer and seller", "A marketing document", "A loan application", "An insurance policy"]', '["Un contrato legalmente vinculante entre comprador y vendedor", "Un documento de mercadeo", "Una solicitud de préstamo", "Una póliza de seguro"]', 0, 'A purchase agreement is a legally binding contract that outlines the terms and conditions of a real estate sale.', 'Un contrato de compra es un contrato legalmente vinculante que describe los términos y condiciones de una venta de bienes raíces.', true, '2026-01-14 18:28:35.457846', '2026-01-14 18:28:35.457846') ON CONFLICT (id) DO NOTHING;
